# Pulumi ComponentResource: WebAppInfrastructure

## Project layout

```
webapp-infra/
├── Pulumi.yaml
├── Pulumi.dev.yaml
├── Pulumi.prod.yaml
├── package.json
├── tsconfig.json
├── index.ts
└── lib/
    └── webApp.ts
```

## Pulumi.yaml

```yaml
name: webapp-infra
runtime: nodejs
description: Stateless web app infrastructure (S3, RDS, IAM)
```

## Pulumi.dev.yaml

```yaml
config:
  aws:region: us-east-1

  webapp-infra:environment: dev
  webapp-infra:dbInstanceClass: db.t3.micro
  webapp-infra:dbMultiAz: false
  webapp-infra:dbEncrypted: false
  webapp-infra:bucketReplicaRegion: ""   # no replication in dev
  webapp-infra:dbUsername: webapp_admin
  webapp-infra:dbPassword:
    secure: AAABALh...  # encrypted via Pulumi secrets (ConfigSecret)
  webapp-infra:replicaRegion: ""
```

## Pulumi.prod.yaml

```yaml
config:
  aws:region: us-east-1

  webapp-infra:environment: prod
  webapp-infra:dbInstanceClass: db.t3.medium
  webapp-infra:dbMultiAz: true
  webapp-infra:dbEncrypted: true
  webapp-infra:bucketReplicaRegion: us-west-2
  webapp-infra:dbUsername: webapp_admin
  webapp-infra:dbPassword:
    secure: AAABAMx...
```

## lib/webApp.ts — the ComponentResource

```typescript
import * as pulumi from "@pulumi/pulumi";
import * as aws from "@pulumi/aws";

export interface WebAppArgs {
    environment: string;
    dbInstanceClass: string;
    dbMultiAz: boolean;
    dbEncrypted: boolean;
    bucketReplicaRegion?: string; // set for prod → enables cross-region replication
    dbUsername: string;
    dbPassword: pulumi.Output<string>; // secret — never plaintext
}

export class WebApp extends pulumi.ComponentResource {
    public readonly bucketName: pulumi.Output<string>;
    public readonly dbEndpoint: pulumi.Output<string>;
    public readonly iamRoleArn: pulumi.Output<string>;
    public readonly dbConnSecret: pulumi.Output<string>;

    constructor(name: string, args: WebAppArgs, opts?: pulumi.ComponentResourceOptions) {
        super("webapp:infra:WebApp", name, args, opts);

        const tags = { Environment: args.environment, ManagedBy: "pulumi" };
        const isProd = args.environment === "prod";

        // --- Child options: children inherit the component's URN ---
        const childOpts = { parent: this };

        // ---------------------------------------------------------
        // 1. S3 bucket: versioned, encrypted, private (+ replication in prod)
        // ---------------------------------------------------------
        const bucket = new aws.s3.Bucket(`${name}-assets`, {
            tags,
            versioning: { enabled: true },
            serverSideEncryptionConfiguration: {
                rule: {
                    applyServerSideEncryptionByDefault: {
                        sseAlgorithm: "aws:kms",
                        kmsMasterKeyId: aws.kms.Alias.get(
                            "s3", "alias/aws/s3", {}, childOpts,
                        ).arn,
                    },
                },
            },
            // Block all public access
            publicAccessBlock: undefined, // handled explicitly below
        }, childOpts);

        const publicAccessBlock = new aws.s3.BucketPublicAccessBlock(
            `${name}-assets-pab`,
            {
                bucket: bucket.id,
                blockPublicAcls: true,
                blockPublicPolicy: true,
                ignorePublicAcls: true,
                restrictPublicBuckets: true,
            },
            childOpts,
        );

        // Cross-region replication (prod only)
        if (args.bucketReplicaRegion) {
            const replicaBucket = new aws.s3.Bucket(
                `${name}-assets-replica`,
                {
                    tags,
                    versioning: { enabled: true },
                },
                { ...childOpts, provider: new aws.Provider(`${name}-replica-provider`, {
                    region: args.bucketReplicaRegion,
                }, { parent: this }) },
            );

            const replicationRole = new aws.iam.Role(`${name}-replication-role`, {
                assumeRolePolicy: aws.iam.assumeRolePolicyForPrincipal({
                    Service: "s3.amazonaws.com",
                }),
            }, childOpts);

            new aws.iam.RolePolicy(`${name}-replication-policy`, {
                role: replicationRole.id,
                policy: pulumi.all([bucket.arn, replicaBucket.arn]).apply(([src, dst]) =>
                    JSON.stringify({
                        Version: "2012-10-17",
                        Statement: [{
                            Effect: "Allow",
                            Action: [
                                "s3:GetReplicationConfiguration",
                                "s3:ListBucket",
                                "s3:GetObjectVersionForReplication",
                                "s3:GetObjectVersionAclForReplication",
                                "s3:ReplicateObject",
                                "s3:ReplicateDelete",
                            ],
                            Resource: [src, dst, `${src}/*`, `${dst}/*`],
                        }],
                    }),
                ),
            }, childOpts);

            new aws.s3.BucketReplicationConfig(`${name}-replication`, {
                bucket: bucket.id,
                role: replicationRole.arn,
                rules: [{
                    status: "Enabled",
                    destination: { bucket: replicaBucket.arn },
                }],
            }, { ...childOpts, dependsOn: [publicAccessBlock] });
        }

        // ---------------------------------------------------------
        // 2. RDS PostgreSQL: deletion protection, backups, private
        // ---------------------------------------------------------
        const dbSubnetGroup = new aws.rds.SubnetGroup(`${name}-dbsng`, {
            subnetIds: aws.ec2.getSubnets(
                { filters: [{ name: "tag:Name", values: ["private-*"] }] },
                { parent: this },
            ).then(r => r.ids),
        }, childOpts);

        const db = new aws.rds.Instance(`${name}-postgres`, {
            engine: "postgres",
            engineVersion: "16.4",
            instanceClass: args.dbInstanceClass,
            allocatedStorage: 20,
            dbSubnetGroupName: dbSubnetGroup.name,
            username: args.dbUsername,
            password: args.dbPassword, // secret
            multiAz: args.dbMultiAz,
            storageEncrypted: args.dbEncrypted,
            deletionProtection: true, // acceptance criterion: always on
            skipFinalSnapshot: !isProd,
            finalSnapshotIdentifier: isProd
                ? `${name}-final-snapshot`
                : undefined,
            backupRetentionPeriod: 7, // >= 7 days per spec
            publiclyAccessible: false,
            autoMinorVersionUpgrade: true,
            tags,
        }, childOpts);

        // Connection string stays an encrypted secret output
        const connString = pulumi
            .all([db.endpoint, args.dbUsername, args.dbPassword])
            .apply(([ep, user, pw]) =>
                `postgresql://${user}:${pw}@${ep}/webapp`,
            );

        // ---------------------------------------------------------
        // 3. IAM role for service accounts (least privilege, no wildcards)
        // ---------------------------------------------------------
        // OIDC trust for IRSA (prod); in dev allow a service principal is
        // acceptable, but we use OIDC in both for consistency.
        const eksCluster = aws.eks.getClusterOutput({ name: `${name}-eks` }, childOpts);
        const oidcIssuer = eksCluster.identity.apply(id =>
            id[0].oidc[0].issuer.replace(/^https:\/\//, ""),
        );

        const appRole = new aws.iam.Role(`${name}-app-role`, {
            assumeRolePolicy: oidcIssuer.apply(issuer =>
                JSON.stringify({
                    Version: "2012-10-17",
                    Statement: [{
                        Effect: "Allow",
                        Principal: { Federated: `arn:aws:iam::${aws.getCallerIdentityOutput(childOpts).accountId}:oidc-provider/${issuer}` },
                        Action: "sts:AssumeRoleWithWebIdentity",
                        Condition: {
                            StringEquals: {
                                [`${issuer}:sub`]:
                                    `system:serviceaccount:webapp:webapp-sa`,
                            },
                        },
                    }],
                }),
            ),
            tags,
        }, childOpts);

        new aws.iam.RolePolicy(`${name}-app-policy`, {
            role: appRole.id,
            policy: pulumi.all([bucket.arn]).apply(([bucketArn]) =>
                JSON.stringify({
                    Version: "2012-10-17",
                    Statement: [
                        {
                            Effect: "Allow",
                            Action: ["s3:GetObject", "s3:PutObject"],
                            Resource: `${bucketArn}/*`, // scoped, not "*"
                        },
                        {
                            Effect: "Allow",
                            Action: ["s3:ListBucket"],
                            Resource: bucketArn,
                        },
                    ],
                }),
            ),
        }, childOpts);

        // Expose outputs
        this.bucketName = bucket.id;
        this.dbEndpoint = db.endpoint;
        this.iamRoleArn = appRole.arn;
        this.dbConnSecret = connString;

        super.registerOutputs({
            bucketName: this.bucketName,
            dbEndpoint: this.dbEndpoint,
            iamRoleArn: this.iamRoleArn,
        });
    }
}
```

## index.ts — stack entry point

```typescript
import * as pulumi from "@pulumi/pulumi";
import { WebApp } from "./lib/webApp";

const cfg = new pulumi.Config();
const env = cfg.require("environment");

const webApp = new WebApp("webapp", {
    environment: env,
    dbInstanceClass: cfg.require("dbInstanceClass"),
    dbMultiAz: cfg.getBoolean("dbMultiAz") ?? false,
    dbEncrypted: cfg.getBoolean("dbEncrypted") ?? false,
    bucketReplicaRegion: cfg.get("bucketReplicaRegion") || undefined,
    dbUsername: cfg.require("dbUsername"),
    dbPassword: cfg.requireSecret("dbPassword"), // ConfigSecret — never plaintext
});

export const bucketName = webApp.bucketName;
export const dbEndpoint = webApp.dbEndpoint;
export const iamRoleArn = webApp.iamRoleArn;
// Note: dbConnSecret intentionally NOT exported to avoid accidental plaintext
```

